if(env_value('DB_DATABASE')!=='perigallo_reservation_qa'||!in_array(env_value('DB_HOST'),['127.0.0.1','localhost'],true)||env_value('APP_ENV')==='production'){echo "SKIP reservation payments: isolated QA database required\n";exit(0);}
putenv('REDSYS_ENV=test');putenv('PAYMENT_ENVIRONMENT=sandbox');putenv('REDSYS_MERCHANT_CODE=999008881');putenv('REDSYS_TERMINAL=1');putenv('REDSYS_SIGNATURE_VERSION=HMAC_SHA256_V1');putenv('REDSYS_TEST_SECRET_KEY='.base64_encode(str_repeat('q',24)));putenv('TICKET_QR_ENCRYPTION_KEY='.base64_encode(str_repeat('q',32)));
$p=Database::pdo();$t=new Ticketing($p,new Redsys(),new Mailer());
function keyForTest():string{return bin2hex(random_bytes(16));}
function check($actual,$expected,string $label):void{if($actual!==$expected)throw new RuntimeException($label.': '.json_encode([$actual,$expected]));}
function rejected(callable $f,string $label):void{try{$f();}catch(InvalidArgumentException|RuntimeException $e){if($e instanceof PDOException)throw $e;return;}throw new RuntimeException('Expected rejection: '.$label);}
function fixture(int $capacity=40):array{global $p,$t;$event=$t->adminCreateEvent(['title'=>'QA Reservas '.keyForTest(),'capacity'=>$capacity]);$id=(int)$event['id'];$p->prepare('UPDATE events SET status="published",visible=1 WHERE id=?')->execute([$id]);$type=$t->adminCreateTicketType($id,['name'=>'Adulto','price_cents'=>6500,'capacity'=>$capacity,'tax_rate'=>0]);$p->prepare('UPDATE ticket_types SET status="on_sale",visible=1 WHERE id=?')->execute([$type['id']]);return ['request_id'=>keyForTest(),'event_id'=>$id,'ticket_type_id'=>(int)$type['id'],'first_name'=>'Juan','last_name'=>'García','phone'=>'600000000','quantity'=>8];}
function pay(array $r,string $amount,string $method='cash'):array{global $t;return $t->adminReservationPayment((int)$r['order']['id'],['request_id'=>keyForTest(),'expected_revision'=>$r['order']['reservation_revision'],'amount_euros'=>$amount,'method'=>$method],'qa');}
function callback(array $form,string $response='0000',?int $overrideAmount=null,bool $badSignature=false,array $overrides=[]):array{global $t;$gateway=new Redsys();$request=$gateway->decodeMerchantParameters($form['fields']['Ds_MerchantParameters']);$data=['DS_ORDER'=>$request['DS_MERCHANT_ORDER'],'DS_AMOUNT'=>(string)($overrideAmount??(int)$request['DS_MERCHANT_AMOUNT']),'DS_CURRENCY'=>'978','DS_MERCHANTCODE'=>'999008881','DS_TERMINAL'=>'001','DS_TRANSACTIONTYPE'=>'0','DS_RESPONSE'=>$response,'DS_AUTHORISATIONCODE'=>'QA-LOCAL'];$data=array_replace($data,$overrides);$encoded=$gateway->encodeMerchantParameters($data);return $t->processRedsysNotification(['Ds_MerchantParameters'=>$encoded,'Ds_SignatureVersion'=>'HMAC_SHA256_V1','Ds_Signature'=>$badSignature?'invalid':$gateway->sign($encoded,$data['DS_ORDER'])]);}
function qaPaymentLink(array $r,string $amount):array{global $t;return $t->adminReservationLink((int)$r['order']['id'],['request_id'=>keyForTest(),'expected_revision'=>$r['order']['reservation_revision'],'amount_euros'=>$amount],'qa');}
function activeTickets(int $id):int{global $p;return (int)$p->query('SELECT COUNT(*) FROM tickets t JOIN ticket_order_items i ON i.id=t.order_item_id WHERE i.order_id='.$id.' AND t.status="issued"')->fetchColumn();}
if(($argv[1]??'')==='pay-race'){$body=json_decode(base64_decode($argv[2]),true);try{$t->adminReservationPayment((int)$body['order_id'],$body,'race');echo 'paid';}catch(RuntimeException $e){echo 'conflict';}exit(0);}
if(($argv[1]??'')==='race'){$body=json_decode(base64_decode($argv[2]),true);try{$t->adminCreateReservation($body,'race',true);echo 'reserved';}catch(RuntimeException $e){echo 'full';}exit(0);}

// Safe/idempotent schema; all prior migrations run only against this isolated DB.
if(!$p->query("SHOW TABLES LIKE 'events'")->fetchColumn())foreach(glob(dirname(__DIR__).'/database/migrations/*.sql') as $file)$p->exec(file_get_contents($file));
$p->exec(file_get_contents(dirname(__DIR__).'/database/migrations/032_reservation_payments.sql'));
$body=fixture();$r=$t->adminCreateReservation($body,'qa',true);$id=(int)$r['order']['id'];check($r['order']['total_cents'],52000,'520 EUR total');check($r['order']['paid_cents'],0,'unpaid');check($r['order']['occupancy_status'],'confirmed','independent occupancy');check(activeTickets($id),0,'no active QR before payment');$e=$t->adminGetEvent($body['event_id']);check((int)$e['reserved'],8,'reserved seats, not sold');check((int)$e['sold'],0,'no sale before money');
check((int)$t->adminCreateReservation($body,'qa',true)['order']['id'],$id,'creation idempotency');$changed=$body;$changed['quantity']=9;rejected(fn()=>$t->adminCreateReservation($changed,'qa',true),'changed request key');
$receipt=['request_id'=>keyForTest(),'expected_revision'=>$r['order']['reservation_revision'],'amount_euros'=>'120','method'=>'cash'];$r=$t->adminReservationPayment($id,$receipt,'qa');$r=$t->adminReservationPayment($id,$receipt,'qa');check(count($r['payments']),1,'manual idempotency');check($r['order']['paid_cents'],12000,'partial cash');check($r['order']['outstanding_cents'],40000,'pending 400');rejected(fn()=>$t->adminReservationPayment($id,$receipt+['extra'=>'ignored'],'qa',true),'refund requires confirmation');
$e=$t->adminGetEvent($body['event_id']);check((int)$e['revenue_cents'],12000,'partial event revenue');$report=$t->adminEventPaymentReport($body['event_id']);check((int)$report['totals']['cash_cents'],12000,'cash report includes partial receipts');$door=$t->adminEventAttendees($body['event_id'],true);check(count($door['pending_reservations']),1,'pending reservation on door list');check((int)$door['pending_reservations'][0]['outstanding_cents'],40000,'door shows debt, not total');
$r=qaPaymentLink($r,'200');$token=$r['links'][0]['public_token'];$form=$t->startReservationLink($token);check($t->startReservationLink($token),$form,'same gateway attempt on retry');check($t->adminReservationDetail($id)['order']['paid_cents'],12000,'opening link not payment');rejected(fn()=>pay($t->adminReservationDetail($id),'201'),'processing amount reserved');rejected(fn()=>$t->adminCancelReservation($id,['expected_revision'=>$r['order']['reservation_revision'],'reason'=>'QA'],'qa'),'cannot release seats during charge');
rejected(fn()=>callback($form,'0000',19999),'signed wrong amount');rejected(fn()=>callback($form,'0000',null,false,['DS_CURRENCY'=>'840']),'wrong currency');rejected(fn()=>callback($form,'0000',null,false,['DS_MERCHANTCODE'=>'other']),'wrong merchant');rejected(fn()=>callback($form,'0000',null,false,['DS_TERMINAL'=>'002']),'wrong terminal');rejected(fn()=>callback($form,'0000',null,true),'invalid signature');check($t->adminReservationDetail($id)['order']['paid_cents'],12000,'bad notification no money');callback($form,'0000',null,false,['DS_CARD_NUMBER'=>'do-not-store']);check((int)$p->query("SELECT COUNT(*) FROM payment_attempts WHERE raw_response LIKE '%do-not-store%'")->fetchColumn(),0,'card data never stored');$r=$t->adminReservationDetail($id);check($r['order']['paid_cents'],32000,'online 200');check($r['order']['outstanding_cents'],20000,'debt 200');callback($form);callback($form,'0190');check($t->adminReservationDetail($id)['order']['paid_cents'],32000,'duplicates and later denial do not erase accepted payment');
$r=pay($r,'200','card_present');check($r['order']['economic_status'],'paid','paid after mixed methods');check($r['order']['outstanding_cents'],0,'fully paid');check(activeTickets($id),8,'exactly 8 QR');check(count($r['payments']),3,'three receipts');$report=$t->adminEventPaymentReport($body['event_id']);check((int)$report['totals']['total_cents'],52000,'report actual total');check((int)$report['totals']['cash_cents'],12000,'cash breakdown');check((int)$report['totals']['card_online_cents'],20000,'online breakdown');check((int)$report['totals']['card_present_cents'],20000,'TPV breakdown');rejected(fn()=>pay($r,'1'),'no overpayments');
// Edits preserve receipts and revoke/add unused QR without duplicates.
$edit=['first_name'=>'Juan','last_name'=>'García','phone'=>'600000000','quantity'=>9,'expected_revision'=>$r['order']['reservation_revision']];$r=$t->adminUpdateReservation($id,$edit,'qa',true);check($r['order']['outstanding_cents'],6500,'more seats recompute debt');check(activeTickets($id),0,'QR blocked until new debt paid');$r=pay($r,'65','bank_transfer');check(activeTickets($id),9,'one new QR after payment');$edit['quantity']=8;$edit['expected_revision']=$r['order']['reservation_revision'];rejected(fn()=>$t->adminUpdateReservation($id,$edit,'qa',true),'cannot reduce below receipts');
$refund=['request_id'=>keyForTest(),'expected_revision'=>$r['order']['reservation_revision'],'amount_euros'=>'65','method'=>'bank_transfer','confirmed'=>true];$r=$t->adminReservationPayment($id,$refund,'qa',true);$r=$t->adminReservationPayment($id,$refund,'qa',true);check((int)$r['order']['refunded_cents'],6500,'refund idempotency');$edit['expected_revision']=$r['order']['reservation_revision'];$r=$t->adminUpdateReservation($id,$edit,'qa',true);check(activeTickets($id),8,'unused extra QR cancelled');check($r['order']['economic_status'],'paid','new total settled after refund');
rejected(fn()=>$t->adminCancelOrder($id,'qa','legacy'),'legacy cancellation cannot bypass ledger');rejected(fn()=>$t->adminRecordRefund($id,'qa','legacy'),'legacy refund cannot bypass ledger');$r=$t->adminCancelReservation($id,['expected_revision'=>$r['order']['reservation_revision'],'reason'=>'Cancelled in QA'],'qa');check($r['order']['paid_cents'],52000,'cancellation retains received money');check(activeTickets($id),0,'cancel disables QR');check((int)$t->adminGetEvent($body['event_id'])['available'],40,'cancel releases capacity');
$oldRevision=$r['order']['reservation_revision'];rejected(fn()=>$t->adminReservationPayment($id,['request_id'=>keyForTest(),'expected_revision'=>$oldRevision-1,'amount_euros'=>'1','method'=>'cash'],'qa'),'stale revision');
// Price editing is owner-only, contact-only edits remain possible for administrators.
$newBody=fixture();$newBody['quantity']=2;$newBody['unit_price_euros']='50';rejected(fn()=>$t->adminCreateReservation($newBody,'operator',false),'operator cannot override price');unset($newBody['unit_price_euros']);$new=$t->adminCreateReservation($newBody,'operator',false);$new=qaPaymentLink($new,'100');$cancelledLink=$new['links'][0];$new=$t->adminCancelReservationLink((int)$new['order']['id'],(int)$cancelledLink['id'],['expected_revision'=>$new['order']['reservation_revision']],'qa');rejected(fn()=>$t->startReservationLink($cancelledLink['public_token']),'cancelled link cannot charge');
$new=qaPaymentLink($new,'100');$expired=$new['links'][0];$p->prepare('UPDATE ticket_reservation_links SET expires_at=DATE_SUB(NOW(),INTERVAL 1 DAY) WHERE id=?')->execute([$expired['id']]);check($t->reservationPublicLink($expired['public_token'])['status'],'expired','link expiry');rejected(fn()=>$t->startReservationLink($expired['public_token']),'expired link cannot charge');
// Temporary holds do not expire after full settlement; manual reconciliation is explicit.
$expiring=fixture();$expiring['quantity']=1;$expiring['reservation_expires_at']=date('Y-m-d H:i:s',time()+3600);$temp=$t->adminCreateReservation($expiring,'qa',true);$temp=pay($temp,'65');check($temp['order']['reservation_expires_at'],null,'full payment clears expiry');
$lateBody=fixture();$lateBody['quantity']=1;$late=$t->adminCreateReservation($lateBody,'qa',true);$late=qaPaymentLink($late,'65');$lateLink=$late['links'][0];$lateForm=$t->startReservationLink($lateLink['public_token']);$late=$t->adminReservationDetail((int)$late['order']['id']);
rejected(fn()=>$t->adminCancelReservationLink((int)$late['order']['id'],(int)$lateLink['id'],['expected_revision'=>$late['order']['reservation_revision']],'qa',true),'processing requires external verification');
$late=$t->adminCancelReservationLink((int)$late['order']['id'],(int)$lateLink['id'],['expected_revision'=>$late['order']['reservation_revision'],'confirmed_no_charge'=>true,'reason'=>'Verified in QA gateway'],'qa',true);$late=pay($late,'65');callback($lateForm);$late=$t->adminReservationDetail((int)$late['order']['id']);check($late['order']['credit_cents'],6500,'unexpected late payment is retained as credit');check($late['order']['review_cents'],6500,'late capture needs review');check(activeTickets((int)$late['order']['id']),1,'late callback never duplicates tickets');

// Cancelling a failed old link or replaying its denial never restores an obsolete expiry.
$temporary=fixture();$temporary['quantity']=1;$temporary['reservation_expires_at']=date('Y-m-d H:i:s',time()+3600);$temporary=$t->adminCreateReservation($temporary,'qa',true);$temporary=qaPaymentLink($temporary,'65');$failedLink=$temporary['links'][0];$failedForm=$t->startReservationLink($failedLink['public_token']);callback($failedForm,'0190');$temporary=$t->adminReservationDetail((int)$temporary['order']['id']);
$temporary=$t->adminUpdateReservation((int)$temporary['order']['id'],['first_name'=>'Juan','last_name'=>'García','phone'=>'600000000','quantity'=>1,'occupancy_status'=>'confirmed','reservation_expires_at'=>'','expected_revision'=>$temporary['order']['reservation_revision']],'qa',true);callback($failedForm,'0190');$temporary=$t->adminCancelReservationLink((int)$temporary['order']['id'],(int)$failedLink['id'],['expected_revision'=>$temporary['order']['reservation_revision']],'qa');check($temporary['order']['reservation_expires_at'],null,'old failed link never changes revised expiry');

// Audit failure must roll back the receipt, state and generated QR together.
$faultBody=fixture();$faultBody['quantity']=1;$fault=$t->adminCreateReservation($faultBody,'qa',true);$p->exec('DROP TRIGGER IF EXISTS qa_reservation_audit_failure');$p->exec("CREATE TRIGGER qa_reservation_audit_failure BEFORE INSERT ON ticket_admin_audit_logs FOR EACH ROW BEGIN IF NEW.actor='qa-force-audit-failure' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='QA audit fault'; END IF; END");
try{try{$t->adminReservationPayment((int)$fault['order']['id'],['request_id'=>keyForTest(),'expected_revision'=>$fault['order']['reservation_revision'],'amount_euros'=>'65','method'=>'cash'],'qa-force-audit-failure');throw new RuntimeException('Audit fault was not propagated');}catch(PDOException $expected){}}finally{$p->exec('DROP TRIGGER qa_reservation_audit_failure');}
check($t->adminReservationDetail((int)$fault['order']['id'])['order']['paid_cents'],0,'audit failure rolls back money');check(activeTickets((int)$fault['order']['id']),0,'audit failure rolls back QR');
// Two administrators cannot collect more than the same outstanding balance.
$fundsBody=fixture();$fundsBody['quantity']=1;$funds=$t->adminCreateReservation($fundsBody,'qa',true);$processes=[];
for($i=0;$i<2;$i++){$payload=['order_id'=>$funds['order']['id'],'request_id'=>keyForTest(),'expected_revision'=>$funds['order']['reservation_revision'],'amount_euros'=>'40','method'=>'cash'];$pipes=[];$proc=proc_open([PHP_BINARY,__FILE__,'pay-race',base64_encode(json_encode($payload))],[1=>['pipe','w'],2=>['pipe','w']],$pipes);$processes[]=[$proc,$pipes];}
$results=[];foreach($processes as [$proc,$pipes]){$results[]=trim(stream_get_contents($pipes[1]));$errors=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($proc)!==0)throw new RuntimeException($errors);}sort($results);check($results,['conflict','paid'],'concurrent receipt lock');check($t->adminReservationDetail((int)$funds['order']['id'])['order']['paid_cents'],4000,'only one concurrent receipt');

// Two real processes compete for 5 seats: only one group of 3 may commit.
$race=fixture(5);$race['quantity']=3;$processes=[];for($i=0;$i<2;$i++){$race['request_id']=keyForTest();$pipes=[];$proc=proc_open([PHP_BINARY,__FILE__,'race',base64_encode(json_encode($race))],[1=>['pipe','w'],2=>['pipe','w']],$pipes);$processes[]=[$proc,$pipes];}$results=[];foreach($processes as [$proc,$pipes]){$results[]=trim(stream_get_contents($pipes[1]));$errors=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($proc)!==0)throw new RuntimeException($errors);}sort($results);check($results,['full','reserved'],'concurrent capacity lock');
echo "PASS reservation lifecycle, mixed payments, signed callbacks, reports, refunds, idempotency, permissions, QR and concurrent capacity\n";
